&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-parastyle=&quot;Normal (Web)&quot;&gt;Drive root-cause investigations and corrective actions&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;Normal (Web)&quot;&gt;&amp;nbsp;when necessary, including&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;Normal (Web)&quot;&gt;&amp;nbsp;build non-conformances, test anomalies, and vehicle integration issues.&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:true,&amp;quot;134233118&amp;quot;:true,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
