&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Demonstrated ability to work cross-functionally with design, structures, manufacturing, and test teams to turn analysis into sound hardware decisions.&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Demonstrated excellent verbal and written communication skills.&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Proven ability to work effectively in a fast-paced environment.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233279&amp;quot;:false,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:120,&amp;quot;335559740&amp;quot;:276}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233279&amp;quot;:false,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:120,&amp;quot;335559740&amp;quot;:276}&quot;&gt;&lt;span data-teams=&quot;true&quot;&gt;&lt;strong&gt;Must have the ability to obtain and maintain a U.S. government Secret/Top Secret security clearance.&amp;nbsp;&lt;/strong&gt;&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-charstyle=&quot;Strong&quot;&gt;Desired Qualifications:&lt;/span&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-parastyle=&quot;text-start&quot;&gt;Master’s degree in Aerospace Engineering&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;text-start&quot;&gt;, Mechanical Engineering, Engineering Mechanics, a related field, or equivalent experience.&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Experience owning both&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&amp;nbsp;loads / structural dynamics and multibody dynamics analysis&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt; for a vehicle or mechanism development program.&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Experience with&amp;nbsp;&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;deployment mechanisms, separation systems, release events, or payload delivery systems.&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Experience generating&amp;nbsp;&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;design loads and dynamic requirements&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt; used to size structures, mechanisms, and interfaces.&lt;/span&gt;&lt;/li&gt;
