&lt;ul&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-parastyle=&quot;Normal (Web)&quot;&gt;5&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;Normal (Web)&quot;&gt;+ years of software development experience with a&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;Normal (Web)&quot;&gt;Bachelor’s&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;Normal (Web)&quot;&gt; degree or equivalent experience.&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-parastyle=&quot;Normal (Web)&quot;&gt;Experience working in a systems level language like Rust, C++, or C.&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-parastyle=&quot;Normal (Web)&quot;&gt;Experience working in a Linux development environment.&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;Experience with tools and processes&amp;nbsp;related&amp;nbsp;to&amp;nbsp;software&amp;nbsp;development&amp;nbsp;such as&amp;nbsp;version control,&amp;nbsp;code reviews, issue tracking,&amp;nbsp;and&amp;nbsp;CI/CD environments.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559738&amp;quot;:100,&amp;quot;335559739&amp;quot;:100,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
