&lt;ul&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Manage cloud services (AWS, Azure, or GCP) including provisioning, monitoring, and cost control aligned with program requirements.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Experience managing,&amp;nbsp;maintaining, and&amp;nbsp;optimizing&amp;nbsp;Windows and Linux&amp;nbsp;(RHEL preferred)&amp;nbsp;environments.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Experience with containerized environments&amp;nbsp;i.e.&amp;nbsp;Docker and Kubernetes&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Configure,&amp;nbsp;maintain, and secure network devices, firewalls, VPNs, and segmented networks used in controlled environments.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Conduct system patching, updates, hardening, and continuous monitoring to meet security and compliance standards.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Implement and&amp;nbsp;maintain&amp;nbsp;technical controls aligned with frameworks commonly used in defense contracting (e.g.,&amp;nbsp;ITAR,&amp;nbsp;NIST,&amp;nbsp;DFARS)&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
